def find_counterexample(S, d, M):
    # Search for a sequence x_i in [1, M] such that no subset sum is in [S-d, S+d]
    # and sum(x_i) >= S.
    # To avoid the interval [S-d, S+d], any subset sum T must be T < S-d or T > S+d.

    target_low = S - d
    target_high = S + d

    # We can use a recursive search.
    def is_valid(xs):
        sums = {0}
        for x in xs:
            new_sums = set()
            for s in sums:
                new_s = s + x
                if target_low <= new_s <= target_high:
                    return False
                new_sums.add(new_s)
            sums.update(new_sums)
        return True

    # This is still too slow. Let's try a greedy approach with random restarts.
    for _ in range(10000):
        xs = []
        current_sum = 0
        while current_sum < S:
            x = random.randint(1, M)
            if is_valid(xs + [x]):
                xs.append(x)
                current_sum += x
            else:
                # Try another x
                found = False
                for x_alt in range(M, 0, -1):
                    if is_valid(xs + [x_alt]):
                        xs.append(x_alt)
                        current_sum += x_alt
                        found = True
                        break
                if not found:
                    break
        if current_sum >= S:
            return xs
    return None

