import random

def get_min_dist(S, xs):
    sums = {0}
    for x in xs:
        new_sums = set()
        for s in sums:
            new_sums.add(s + x)
        sums.update(new_sums)

    min_d = float('inf')
    for s in sums:
        min_d = min(min_d, abs(s - S))
    return min_d

def solve():
    S = 1810
    M = 100
    best_d = 46
    best_seq = [98] * 19

    for _ in range(10000):
        # Mutate the current best sequence
        xs = list(best_seq)
        mutation_type = random.randint(0, 2)
        if mutation_type == 0:
            # Change one element
            idx = random.randint(0, len(xs)-1)
            xs[idx] = random.randint(1, M)
        elif mutation_type == 1:
            # Add an element
            xs.append(random.randint(1, M))
        elif mutation_type == 2:
            # Remove an element
            if len(xs) > 1:
                xs.pop(random.randint(0, len(xs)-1))

        if sum(xs) < S:
            continue

        d = get_min_dist(S, xs)
        if d > best_d:
            best_d = d
            best_seq = xs
            print(f"New best_d: {best_d} for seq {xs}")

    return best_d, best_seq

print(solve())
